namespace ghidra.trace.model.memory;



using ghidra.pcode.utils;
using ghidra.program.model.address;
using ghidra.trace.model.target;

public class RegisterValueConverter {
	private TraceObjectValue registerValue;
	private BigInteger value;
	private int bitLength = -1;
	private byte[] be;
	private byte[] le;

	public RegisterValueConverter(TraceObjectValue registerValue) {
		this.registerValue = registerValue;
	}

	public static BigInteger convertValueToBigInteger(object val)
    {
		if (val is string s) {
			try {
				return new BigInteger(s, 16);
			}
			catch (NumberFormatException e) {
				throw new RegisterValueException(
					"Invalid register value " + s + ". Must be hex digits only.");
			}
		}
		else if (val is byte[] arr) {
			// NOTE: Reg object values are always big endian
			return new BigInteger(1, arr);
		}
		else if (val is Byte b) {
			return BigInteger.valueOf(b);
		}
		else if (val is Short s) {
			return BigInteger.valueOf(s);
		}
		else if (val is Integer i) {
			return BigInteger.valueOf(i);
		}
		else if (val is Long l) {
			return BigInteger.valueOf(l);
		}
		else if (val is Address a) {
			return a.getOffsetAsBigInteger();
		}
		throw new RegisterValueException(
			"Cannot convert register value: (" + val.GetType() + ") '" + val + "'");
	}

	BigInteger convertRegisterValueToBigInteger()
    {
		return convertValueToBigInteger(registerValue.getValue());
	}

	int getRegisterValueBitLength()
    {
		object objBitLength = registerValue.getParent()
				.getValue(registerValue.getMinSnap(), TraceRegister.KEY_BITLENGTH)
				.getValue();
		if (!(objBitLength is Number numBitLength)) {
			throw new RegisterValueException(
				"Register length is not numeric: (" + objBitLength.GetType() + ") '" +
					objBitLength + "'");
		}
		return numBitLength.intValue();
	}

	public BigInteger getValue()
    {
		if (value != null) {
			return value;
		}
		return value = convertRegisterValueToBigInteger();
	}

	int getBitLength()
    {
		if (bitLength != -1) {
			return bitLength;
		}
		return bitLength = getRegisterValueBitLength();
	}

	int getByteLength()
    {
		return (getBitLength() + 7) / 8;
	}

	public byte[] getBytesBigEndian()
